package main

import (
	"fmt"
	"runtime"
)

func main() {
	// Allocate garbage, then force a full tricolor cycle to reclaim it.
	for i := 0; i < 10000; i++ {
		_ = make([]byte, 1024) // unreachable after the loop -> white -> swept
	}
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	runtime.GC() // runs a complete mark+sweep cycle synchronously
	runtime.ReadMemStats(&after)
	fmt.Println(after.NumGC > before.NumGC) // Output: true (a cycle completed)
}

package main

import "fmt"

type Node struct{ next *Node }

func main() {
	black := &Node{} // imagine this was already scanned (black)
	white := &Node{} // freshly allocated, not yet marked (white)

	// During the mark phase, this pointer write triggers the compiler-inserted
	// write barrier, which shades `white` grey so it can't be wrongly collected:
	black.next = white // barrier: keeps the tricolor invariant intact

	fmt.Println(black.next == white) // Output: true
}

package main

import (
	"fmt"
	"runtime/debug"
)

func main() {
	old := debug.SetGCPercent(200) // GC only when the heap TRIPLES -> fewer cycles, more RAM
	fmt.Println("previous GOGC:", old) // Output: previous GOGC: 100

	// heap goal with live heap L and GOGC=200 is L*(1 + 200/100) = L*3.
	// Setting -1 disables the ratio trigger entirely (pair with GOMEMLIMIT).
	debug.SetGCPercent(-1)
}

