	prev := debug.SetMemoryLimit(900 << 20) // ~900 MiB soft cap
	fmt.Println(prev)                        // Output: 9223372036854775807 (previous = MaxInt64 = unlimited)

	// Steady-state container pattern: let the limit alone pace the GC.
	debug.SetGCPercent(-1)
}

package main

import (
	"fmt"
	"runtime"
)

func main() {
	// A tight allocation loop makes allocating goroutines pay GC 'assist' tax:
	// each make() may perform a slice of marking work so the heap can't outrun the GC.
	sink := make([][]byte, 0, 100000)
	for i := 0; i < 100000; i++ {
		sink = append(sink, make([]byte, 512)) // high alloc rate -> assist kicks in
	}
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	fmt.Println(m.NumGC > 0) // Output: true (assists helped drive several cycles)
	runtime.KeepAlive(sink)
}

