package main

import (
	"fmt"
	"runtime/debug"
)

func main() {
	// Steady-state pattern: turn GOGC off and let GOMEMLIMIT pace the GC.
	// The runtime now collects as the heap nears 256 MiB, regardless of growth ratio.
	debug.SetGCPercent(-1)             // disable the GOGC-ratio trigger
	debug.SetMemoryLimit(256 << 20)    // soft cap: ~256 MiB total

	processBatch()
	fmt.Println("batch complete")
}

func processBatch() {
	for i := 0; i < 5; i++ {
		_ = make([]byte, 32<<20) // 32 MiB of transient work per step
	}
}

