type Queue struct{ items []*Job }

func (q *Queue) Pop() *Job {
	j := q.items[0]
	q.items[0] = nil      // clear the reference so the GC can reclaim the Job
	q.items = q.items[1:] // now safe to advance the header
	// Optional: when len shrinks far below cap, compact to release the array:
	if len(q.items) == 0 {
		q.items = nil
	}
	return j
}

func AllocBytes(fn func()) uint64 {
	var before, after runtime.MemStats
	runtime.GC()                  // stabilize the baseline
	runtime.ReadMemStats(&before) // cumulative bytes so far
	fn()
	runtime.ReadMemStats(&after)  // cumulative bytes after fn
	return after.TotalAlloc - before.TotalAlloc // bytes fn allocated
}

func SumEvens(nums []int) []int {
	// Pre-size to the maximum possible length so append never reallocates.
	out := make([]int, 0, len(nums)) // single allocation of the right capacity
	for _, n := range nums {
		if n%2 == 0 {
			out = append(out, n) // stays within cap -> no reallocation, no growth garbage
		}
	}
	return out
}
